class Cache:
    def __init__(self, now): self.now, self.data = now, {}
    def set(self, key, value, ttl):
        if ttl <= 0: raise ValueError('ttl must be positive')
        self.data[key] = (value, self.now() + ttl)
    def get(self, key, default=None):
        record = self.data.get(key)
        if record is None: return default
        value, expires = record
        if self.now() >= expires:
            del self.data[key]
            return default
        return value

