from pathlib import Path
def save(path,rows,overwrite=False):
    data=''.join(json.dumps(row,ensure_ascii=False)+'\n' for row in rows);path=Path(path)
    if not overwrite:
        with path.open('x') as output:output.write(data)
        return
    fd,name=tempfile.mkstemp(dir=path.parent,prefix='.export-')
    try:
        with os.fdopen(fd,'w') as output:output.write(data)
        os.replace(name,path)
    finally:
        if os.path.exists(name):os.unlink(name)

